134→    let pointers = [
135→        jsonl_pointer(),
136→        SourcePtr::Git {
137→            repo: PathBuf::from("/work/repo"),
138→            sha: "7f64f5a".to_owned(),
139→        },
140→        SourcePtr::App { action_id: 7 },
141→    ];
142→
143→    for source in pointers {
144→        let event = event_with(source, EventKind::TaskDone);
145→        assert_eq!(event.mapping_version, MappingVersion::LATEST);
146→
147→        let mut value = serde_json::to_value(&event).expect("event serializes");
148→        assert_eq!(value["mapping_version"], "v1");
149→
150→        value
151→            .as_object_mut()
152→            .expect("event is an object")
153→            .remove("mapping_version");
154→        assert!(
155→            serde_json::from_value::<Event>(value).is_err(),
156→            "an event without mapping_version must not deserialize"
157→        );
