162→fn unknown_event_keeps_raw_type_and_byte_offset() {
163→    let kind = EventKind::Unknown {
164→        raw_type: "todo_state".to_owned(),
165→    };
166→    assert_eq!(kind.prd_name(), "unknown.event");
167→    assert_eq!(kind.lane(), None);
