171→    event.lane = Lane::for_role(event.role);
172→
173→    let json = serde_json::to_value(&event).expect("event serializes");
174→    assert_eq!(
175→        json["kind"],
176→        serde_json::json!({"unknown": {"raw_type": "todo_state"}})
