47→/// One thing that happened in a mission (PRD appendix A).
48→#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
49→#[serde(deny_unknown_fields)]
50→pub struct Event {
51→    pub id: EventId,
52→    pub mission_id: MissionId,
53→    pub milestone_id: Option<MilestoneId>,
54→    pub feature_id: Option<FeatureId>,
55→    /// Never `Lane::TimeWasteCost`: that lane is computed, not evented.
56→    pub lane: Lane,
57→    pub kind: EventKind,
58→    pub role: Role,
59→    pub session_id: Option<SessionId>,
60→    pub model: Option<ModelId>,
61→    pub at: Timestamp,
62→    #[serde(rename = "duration_ms", default, with = "duration_ms")]
63→    pub duration: Option<Duration>,
64→    pub usage: Option<TokenUsage>,
65→    pub source: SourcePtr,
66→    pub mapping_version: MappingVersion,
67→}
68→
69→/// `Duration` on the wire is an integer number of milliseconds.
70→mod duration_ms {
71→    use std::time::Duration;
72→
73→    use serde::{Deserialize, Deserializer, Serializer};
74→
75→    pub fn serialize<S: Serializer>(
76→        duration: &Option<Duration>,
77→        serializer: S,
78→    ) -> Result<S::Ok, S::Error> {
79→        match duration {
80→            Some(duration) => {
81→                let millis = u64::try_from(duration.as_millis()).unwrap_or(u64::MAX);
82→                serializer.serialize_some(&millis)
83→            }
84→            None => serializer.serialize_none(),
85→        }
86→    }
87→
88→    pub fn deserialize<'de, D: Deserializer<'de>>(
89→        deserializer: D,
90→    ) -> Result<Option<Duration>, D::Error> {
91→        Ok(Option::<u64>::deserialize(deserializer)?.map(Duration::from_millis))
92→    }
93→}
